get.funcs <- function(name) {
    if (name == "Main spec.") {
        ## temp         temp2
        beta <- c(0.0127183478, -0.0004870903)
        betavcv <- matrix(c(1.054861e-05, -2.859133e-07, -2.859133e-07, 1.059602e-08), 2, 2)
        nlags <- 0
    } else if (name == "Lag 1 spec.") {
        ## temp         temp2       temp.l1      temp2.l1
        beta <- c(0.0130143081, -5.083589e-04, -5.635386e-03, 2.258553e-04)
        betavcv <- matrix(c(1.11245451537199e-05, -3.01913656582653e-07, -2.32136698920191e-06, 6.64885589981278e-08, -3.01913656582653e-07, 1.11560786413704e-08, 6.18637429241252e-08, -2.35257778848148e-09, -2.32136698920191e-06, 6.18637429241252e-08, 1.14947290115945e-05, -3.08270868918464e-07, 6.64885589981278e-08, -2.35257778848148e-09, -3.08270868918464e-07, 1.13008186037368e-08), 4, 4, byrow=T)
        nlags <- 1
    } else if (name == "Lag 5 spec.") {
        ## temp         temp2       temp.l1       temp.l2       temp.l3       temp.l4       temp.l5      temp2.l1      temp2.l2      temp2.l3      temp2.l4      temp2.l5
        beta <- c(0.0097763409874089, -0.000466228820017364, -0.00341459885644201, -0.00701589132521418, -0.00124238867788218, -0.0023900123117433, 0.00217355450976723, 0.000207840069497656, 0.000147866984332855, -0.000106190443955729, 0.000182700252147745, -8.66024013608382e-05)
        betavcv <- matrix(c(1.25699465580772e-05, -3.33592472777594e-07, -1.92886889623436e-06, 6.17809594178396e-07, 1.73778490824485e-06, 2.42001847699306e-06, 1.24428950281543e-06, 5.70946181325951e-08, -1.24014736109823e-08, -3.50693685767841e-08, -5.36755788192761e-08, -3.61695623740053e-08, -3.33592472777594e-07, 1.19930812565681e-08, 5.26867660438475e-08, -2.48270124111287e-08, -2.89317460468207e-08, -5.48821135063758e-08, -3.94900798687305e-08, -2.20206118869267e-09, 7.72215619952887e-10, 5.19835560864667e-10, 1.37939183377647e-09, 1.27030666868064e-09, -1.92886889623436e-06, 5.26867660438475e-08, 1.33769395615856e-05, -2.10953375398289e-06, 2.13935209723477e-07, 1.08894166592446e-06, 2.43691215802775e-06, -3.51763449754354e-07, 6.13897975622374e-08, -6.96517854741852e-09, -1.85884989448218e-08, -5.41993528412058e-08, 6.17809594178396e-07, -2.48270124111287e-08, -2.10953375398289e-06, 1.280354653056e-05, -2.29413098913938e-06, 3.2000439504274e-07, 1.38688833296648e-06, 6.20722706446965e-08, -3.4283460010652e-07, 6.38877891535294e-08, -9.55879708550637e-09, -2.65930449804695e-08, 1.73778490824485e-06, -2.89317460468207e-08, 2.13935209723477e-07, -2.29413098913938e-06, 1.28033429582787e-05, -1.96574864680814e-06, 7.21768271480337e-07, -1.63565331859918e-08, 6.67831944723384e-08, -3.45024994208418e-07, 5.82181915222912e-08, -1.89033782165385e-08, 2.42001847699306e-06, -5.48821135063758e-08, 1.08894166592446e-06, 3.2000439504274e-07, -1.96574864680814e-06, 1.31294776511042e-05, -1.66898028334601e-06, -1.23039735030179e-08, -1.93341084040751e-08, 5.93610716872421e-08, -3.50084518699851e-07, 5.13818825512043e-08, 1.24428950281543e-06, -3.94900798687305e-08, 2.43691215802775e-06, 1.38688833296648e-06, 7.21768271480337e-07, -1.66898028334601e-06, 1.24759103877971e-05, -5.35385063430759e-08, -1.98439814699449e-08, -2.58416012590169e-08, 5.11379586652694e-08, -3.32646549031136e-07, 5.70946181325951e-08, -2.20206118869267e-09, -3.51763449754354e-07, 6.20722706446965e-08, -1.63565331859918e-08, -1.23039735030179e-08, -5.35385063430759e-08, 1.26466214518881e-08, -2.50267204611335e-09, 6.88259976200089e-10, 1.54649754284584e-11, 1.33055488664497e-09, -1.24014736109823e-08, 7.72215619952887e-10, 6.13897975622374e-08, -3.4283460010652e-07, 6.67831944723384e-08, -1.93341084040751e-08, -1.98439814699449e-08, -2.50267204611335e-09, 1.25466323764153e-08, -2.54724841821817e-09, 7.57890770242578e-10, 2.51092275672695e-10, -3.50693685767841e-08, 5.19835560864667e-10, -6.96517854741852e-09, 6.38877891535294e-08, -3.45024994208418e-07, 5.93610716872421e-08, -2.58416012590169e-08, 6.88259976200089e-10, -2.54724841821817e-09, 1.26534325253078e-08, -2.39025879062195e-09, 9.02408612431688e-10, -5.36755788192761e-08, 1.37939183377647e-09, -1.85884989448218e-08, -9.55879708550637e-09, 5.82181915222912e-08, -3.50084518699851e-07, 5.11379586652694e-08, 1.54649754284584e-11, 7.57890770242578e-10, -2.39025879062195e-09, 1.26854978366348e-08, -2.12037318628315e-09, -3.61695623740053e-08, 1.27030666868064e-09, -5.41993528412058e-08, -2.65930449804695e-08, -1.89033782165385e-08, 5.13818825512043e-08, -3.32646549031136e-07, 1.33055488664497e-09, 2.51092275672695e-10, 9.02408612431688e-10, -2.12037318628315e-09, 1.20621428750769e-08), 12, 12, byrow=T)
        nlags <- 5
    }

    coeffs <- mvrnorm(MCNUM, mu=beta, Sigma=betavcv, empirical=T)
    subera5.lags <- list()

    setup <- function(mcii) {
        subera5.lags <<- list()
        if (is.null(mcii))
            return(beta)
        coeffs[mcii, ]
    }

    simulate <- function(coeffs, year, subera5, contemp.only=F) {
        if (length(subera5.lags) < nlags)
            return(subera5$t2m * NA)

        totals <- (subera5$t2m - 273.15) * coeffs[1] + (subera5$t2m - 273.15)^2 * coeffs[2]
        if (!contemp.only && nlags > 0) {
            for (yy in (year - 1):(year - nlags)) {
                totals <- totals + (subera5.lags[[as.character(year - 1)]]$t2m - 273.15) * coeffs[2 + (year - yy)] + (subera5.lags[[as.character(year - 1)]]$t2m - 273.15)^2 * coeffs[2 + nlags + (year - yy)]
            }
        }

        subera5.lags[[as.character(year)]] <<- subera5

        totals
    }

    list(setup=setup, simulate=simulate)
}

if (F) {
    funcs <- get.funcs('Main spec.')
    oneres <- project.single(funcs$setup, funcs$simulate)
    plot((oneres %>% filter(ISO == 'NOR'))$dimpact)
    plot((oneres %>% filter(ISO == 'THA'))$dimpact)
}
